'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const caregivers=[{id:1,name:'Maya Chen',role:'Personal care aide'},{id:2,name:'Jordan Ellis',role:'Companion caregiver'},{id:3,name:'Sofia Rivera',role:'Personal care aide'}];
let clients,visits,logs,tab='overview',selectedCaregiver=1,search='';
const demoDate='2026-09-17',days=['2026-09-14','2026-09-15','2026-09-16','2026-09-17','2026-09-18'];
function seed(){clients=[{id:1,name:'Evelyn Parker',service:'Personal care',address:'120 Example Lane',contact:'Avery Parker · sample contact',notes:'Prefers morning visits. Assist with meal preparation and light housekeeping.'},{id:2,name:'Arthur Bennett',service:'Companionship',address:'48 Sample Court',contact:'Alex Bennett · sample contact',notes:'Enjoys conversation and a short walk when comfortable.'},{id:3,name:'Rosa Mitchell',service:'Homemaker',address:'86 Demo Avenue',contact:'Sam Mitchell · sample contact',notes:'Help with laundry, meal preparation, and tidying common areas.'},{id:4,name:'James Wilson',service:'Personal care',address:'24 Fictional Way',contact:'Taylor Wilson · sample contact',notes:'Afternoon visits preferred. Assist with daily routines.'}];visits=[{id:1,client:1,caregiver:1,date:demoDate,time:'09:00',end:'11:00',status:'Scheduled'},{id:2,client:2,caregiver:2,date:demoDate,time:'10:00',end:'12:00',status:'Scheduled'},{id:3,client:3,caregiver:3,date:demoDate,time:'13:00',end:'15:00',status:'Scheduled'},{id:4,client:4,caregiver:1,date:demoDate,time:'14:00',end:'16:00',status:'Scheduled'},{id:5,client:1,caregiver:1,date:days[4],time:'09:00',end:'11:00',status:'Scheduled'},{id:6,client:2,caregiver:2,date:days[2],time:'10:00',end:'12:00',status:'Completed',checkin:'2026-09-16T10:00:00',checkout:'2026-09-16T12:00:00',tasks:[true,true,true],note:'Sample completed visit.'}];logs=[];}
seed();
const cn=id=>clients.find(c=>c.id===id), cg=id=>caregivers.find(c=>c.id===id), initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join(''), badge=s=>`<span class="badge ${s.toLowerCase().replaceAll(' ','-')}">${esc(s)}</span>`, today=()=>visits.filter(v=>v.date===demoDate).sort((a,b)=>a.time.localeCompare(b.time)), sorted=vs=>[...vs].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function log(s){logs.unshift({text:s,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})})}
function heading(title,sub,action=''){return `<div class="title-row"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function visitRow(v){const c=cn(v.client);return `<div class="visit"><div class="time">${v.time}<small>to ${v.end}</small></div><span class="avatar">${initials(c.name)}</span><div class="visit-info"><strong>${esc(c.name)}</strong><small>${esc(c.service)} · ${esc(cg(v.caregiver).name)}</small></div>${badge(v.status)}</div>`}
function overview(){const ts=today();return heading('A good day starts with great care.','Thursday, September 17 · Sample operations dashboard','<button class="primary" data-action="add-visit">＋ Schedule visit</button>')+`<div class="stats"><div class="stat"><div class="label">Active clients</div><div class="number">${clients.length}</div><small>In your demo workspace</small></div><div class="stat"><div class="label">Visits today</div><div class="number">${ts.length}</div><small>${ts.filter(v=>v.status==='Scheduled').length} waiting to start</small></div><div class="stat featured"><div class="label">Care in progress</div><div class="number">${ts.filter(v=>v.status==='In progress').length}</div><small>Simulated check-ins</small></div><div class="stat"><div class="label">Completed today</div><div class="number">${ts.filter(v=>v.status==='Completed').length}<span style="font-size:18px;color:#91a2ab"> / ${ts.length}</span></div><small>Visit notes available</small></div></div><div class="grid"><section class="card"><div class="card-head"><h2>Today's visits</h2><button class="text" data-go="schedule">View schedule →</button></div>${ts.length?ts.map(visitRow).join(''):'<div class="empty">No visits scheduled today.</div>'}</section><div><section class="card"><div class="card-head"><h2>Your care team</h2><span class="date">3 caregivers</span></div><div class="card-body">${caregivers.map(c=>`<div class="roster-row"><span class="avatar">${initials(c.name)}</span><div><strong style="font-size:14px">${c.name}</strong><small>${c.role}</small></div><span class="badge scheduled">${ts.filter(v=>v.caregiver===c.id).length} visits</span></div>`).join('')}</div></section><div class="callout"><div class="eyebrow">TRY THE CARE JOURNEY</div><h3>From scheduled to completed</h3><p>Open a caregiver's day, start a sample visit, and record the care provided.</p><button class="text" data-go="caregiver">Open caregiver view →</button></div></div></div>`}
function clientsView(){const rows=clients.filter(c=>(c.name+' '+c.service).toLowerCase().includes(search.toLowerCase()));return heading('Clients & intake','A clear view of the people you support.','<button class="primary" data-action="add-client">＋ Add sample client</button>')+`<div class="toolbar"><input id="search" class="search" placeholder="Search clients or services…" aria-label="Search clients" value="${esc(search)}"><span class="date">${rows.length} clients</span></div><section class="card table-wrap"><table><thead><tr><th>CLIENT</th><th>CARE SERVICE</th><th>DEMO ADDRESS</th><th>PROFILE</th></tr></thead><tbody>${rows.map(c=>`<tr><td><div class="name-cell"><span class="avatar">${initials(c.name)}</span><div><strong>${esc(c.name)}</strong><small>Client CW-${String(c.id).padStart(3,'0')}</small></div></div></td><td>${esc(c.service)}</td><td>${esc(c.address)}</td><td><button class="text" data-edit-client="${c.id}">View / edit →</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No clients match your search.</td></tr>'}</tbody></table></section>`}
function scheduleView(){return heading('A week of thoughtful care','September 14–18, 2026 · Demonstration calendar','<button class="primary" data-action="add-visit">＋ Schedule visit</button>')+`<div class="toolbar"><span class="date">Drag a scheduled visit to another day, or select Edit to change its time and caregiver.</span><button class="secondary" data-go="caregiver">Caregiver view</button></div><section class="card table-wrap"><div class="calendar">${days.map((date,i)=>`<div class="day ${date===demoDate?'today':''}" data-day="${date}"><div class="day-head">${['MON','TUE','WED','THU','FRI'][i]}<strong>${14+i}</strong></div>${sorted(visits.filter(v=>v.date===date)).map(v=>`<article class="event" ${v.status==='Scheduled'?'draggable="true"':''} data-visit="${v.id}"><small>${v.time}–${v.end}</small><strong>${esc(cn(v.client).name)}</strong><small>${esc(cg(v.caregiver).name)}</small>${badge(v.status)}<div><button class="text" data-edit-visit="${v.id}">${v.status==='Scheduled'?'Edit visit':'View details'}</button></div></article>`).join('')}</div>`).join('')}</div></section><p class="help">Overlapping assignments for the same caregiver or client are blocked. Dragging is available on desktop; Edit works on all devices.</p>`}
function caregiverView(){const vs=sorted(visits.filter(v=>v.caregiver===selectedCaregiver&&v.date===demoDate));return heading('Caregiver companion','A mobile-friendly view of the day ahead.')+`<div class="phone-layout"><section class="card"><div class="care-header"><div class="eyebrow" style="color:#83cbbc">THURSDAY, SEPTEMBER 17</div><h2>Hello, ${cg(selectedCaregiver).name.split(' ')[0]}.</h2><p>${vs.length} visits on your schedule</p><label for="care-select" style="font-size:13px">Preview caregiver</label><select id="care-select">${caregivers.map(c=>`<option value="${c.id}" ${c.id===selectedCaregiver?'selected':''}>${c.name}</option>`).join('')}</select></div>${vs.map(v=>`<article class="care-card"><div class="toolbar"><span class="date">${v.time}–${v.end}</span>${badge(v.status)}</div><h3>${esc(cn(v.client).name)}</h3><p>${esc(cn(v.client).service)}</p><small>${esc(cn(v.client).address)} · fictional address</small><p class="section-gap" style="font-size:14px">${esc(cn(v.client).notes)}</p>${v.status==='Scheduled'?`<button class="primary" data-checkin="${v.id}">Start simulated visit</button>`:v.status==='In progress'?`<small class="section-gap">Checked in at ${new Date(v.checkin).toLocaleTimeString()}</small><div class="checklist">${['Care plan reviewed','Scheduled support provided','Client feedback recorded'].map((t,i)=>`<label><input type="checkbox" data-task="${v.id}:${i}" ${v.tasks?.[i]?'checked':''}>${t}</label>`).join('')}</div><label class="field">Visit notes<textarea data-note="${v.id}" maxlength="1000" placeholder="Add a short sample visit note…">${esc(v.note||'')}</textarea></label><button class="primary" data-checkout="${v.id}">Complete & check out</button>`:`<div class="callout"><strong>Visit completed</strong><p>${esc(v.note)}</p><small>Actual demo duration: ${Math.max(0,Math.round((new Date(v.checkout)-new Date(v.checkin))/60000))} minutes</small></div>`}</article>`).join('')||'<div class="empty">No visits assigned for today.</div>'}</section><div><section class="card"><div class="card-head"><h2>How to demonstrate a visit</h2></div><div class="card-body"><ol class="steps"><li><strong>Start the visit</strong><small>The prototype records your current timestamp. It does not collect GPS or verify your location.</small></li><li><strong>Record the care provided</strong><small>Complete the three sample tasks and add a visit note.</small></li><li><strong>Complete and review</strong><small>Check out, then return to Overview to see the updated visit status.</small></li></ol><p>Role switching is for demonstration only; it is not an authentication or permission system.</p></div></section><section class="card section-gap"><div class="card-head"><h2>Session activity</h2></div><div class="card-body">${logs.length?logs.slice(0,8).map(l=>`<div class="log">${esc(l.text)}<small>${l.time} · this session</small></div>`).join(''):'<p>Start a sample visit to see activity here.</p>'}</div></section></div></div>`}
function aboutView(){return heading('A working concept, with a clear scope.','Built to demonstrate a proposed workflow, not previous client experience.')+`<div class="split"><section class="card"><div class="card-head"><h2>Working in this prototype</h2></div><div class="card-body"><ul><li>Sample client intake and editable profiles</li><li>Caregiver assignment and visit scheduling</li><li>Drag-and-drop rescheduling with conflict checks</li><li>Responsive caregiver view</li><li>Simulated check-in and check-out timestamps</li><li>Care task checklist and visit notes</li><li>Dashboard counts and session activity</li></ul></div></section><section class="card"><div class="card-head"><h2>Production work still required</h2></div><div class="card-body"><ul><li>Identity, access controls, and a secure backend</li><li>Durable storage, backups, and audit records</li><li>Real EVV, location verification, and state integrations</li><li>Billing, claims, payroll, and payment connections</li><li>Messaging, documents, signatures, and offline support</li><li>Security and applicable compliance validation</li><li>Production testing and operational support</li></ul></div></section></div><div class="callout"><h3>Use fictional information only</h3><p>This is an independently created concept demonstration. It does not represent a previously delivered customer platform and makes no HIPAA or state EVV compliance claim. All records live only in this page's memory and are discarded on refresh. The caregiver view is a responsive web interface, not a native mobile app.</p></div><section class="card section-gap"><div class="card-head"><h2>A three-minute walkthrough</h2></div><div class="card-body"><ol class="steps"><li><strong>Clients & intake</strong><small>Add a fictional client, choose a service, and record their preferences.</small></li><li><strong>Schedule</strong><small>Create a visit on September 17. Assign Maya, Jordan, or Sofia to a free time. Use Edit to adjust the visit.</small></li><li><strong>Caregiver view</strong><small>Select the assigned caregiver, start the visit, complete the checklist, and add a note before checking out.</small></li><li><strong>Overview</strong><small>Show the updated completed-visit count.</small></li></ol></div></section>`}
function render(){const names={overview:'Overview',clients:'Clients & intake',schedule:'Schedule',caregiver:'Caregiver view',about:'About this demo'};$('#crumb').textContent=names[tab];document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});$('#main').innerHTML=({overview,clients:clientsView,schedule:scheduleView,caregiver:caregiverView,about:aboutView})[tab]();}
function go(t){tab=t;render();window.scrollTo({top:0,behavior:'instant'})}
const field=(label,name,value='',type='text',required=true)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="160"></label>`;
const selectField=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(([id,n])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;
function showModal(title,html,save){$('#modal-title').textContent=title;$('#fields').innerHTML=html;$('#form-error').textContent='';$('#submit').hidden=!save;$('#form').onsubmit=e=>{e.preventDefault();try{save(new FormData(e.target));$('#modal').close();render()}catch(err){$('#form-error').textContent=err.message}};$('#modal').showModal();}
function clientModal(id){const c=cn(id)||{};showModal(id?'Client profile':'Add sample client',`<p class="help">Enter fictional details only.</p>`+field('Client name','name',c.name)+selectField('Service','service',['Personal care','Companionship','Homemaker','Respite care'].map(x=>[x,x]),c.service)+field('Sample address','address',c.address)+field('Sample contact','contact',c.contact,'text',false)+`<label class="field">Care preferences<textarea name="notes" maxlength="1000">${esc(c.notes)}</textarea></label>`,f=>{const name=f.get('name').trim(),address=f.get('address').trim();if(!name||!address)throw Error('Enter a name and sample address.');const data={id:id||Math.max(0,...clients.map(c=>c.id))+1,name,address,service:f.get('service'),contact:f.get('contact').trim(),notes:f.get('notes').trim()};if(id)clients[clients.findIndex(c=>c.id===id)]=data;else clients.push(data);log(`${id?'Updated':'Added'} client ${name}`);toast('Client profile saved for this session.');});}
function conflict(candidate,id){return visits.some(v=>v.id!==id&&v.date===candidate.date&&(v.caregiver===candidate.caregiver||v.client===candidate.client)&&candidate.time<v.end&&candidate.end>v.time)}
function visitModal(id){const v=visits.find(v=>v.id===id);if(v&&v.status!=='Scheduled'){showModal('Visit details',`<h3>${esc(cn(v.client).name)}</h3><p>${esc(cg(v.caregiver).name)} · ${v.date} · ${v.time}–${v.end}</p><p>${badge(v.status)}</p><p>${esc(v.note||'No visit note yet.')}</p><small>Visit times cannot be edited after check-in.</small>`,null);return;}showModal(v?'Edit visit':'Schedule a sample visit',selectField('Client','client',clients.map(c=>[c.id,c.name]),v?.client||1)+selectField('Caregiver','caregiver',caregivers.map(c=>[c.id,c.name]),v?.caregiver||1)+selectField('Date · demo week','date',days.map(d=>[d,d]),v?.date||demoDate)+`<div class="split">${field('Start time','time',v?.time||'16:00','time')}${field('End time','end',v?.end||'17:00','time')}</div>`,f=>{const data={id:id||Math.max(0,...visits.map(v=>v.id))+1,client:Number(f.get('client')),caregiver:Number(f.get('caregiver')),date:f.get('date'),time:f.get('time'),end:f.get('end'),status:'Scheduled'};if(data.end<=data.time)throw Error('End time must be later than start time.');if(conflict(data,id))throw Error('This client or caregiver already has a visit at that time. Choose a free time.');if(id)visits[visits.findIndex(v=>v.id===id)]=data;else visits.push(data);log(`Scheduled ${cn(data.client).name} with ${cg(data.caregiver).name}`);toast('Visit saved.');});}
function startVisit(id){const v=visits.find(v=>v.id===id);if(!v||v.status!=='Scheduled')throw Error('This visit cannot be started.');if(v.date!==demoDate)throw Error('Only visits on the sample day can be started.');if(visits.some(x=>x.caregiver===v.caregiver&&x.status==='In progress'))throw Error('Complete the current visit before starting another.');v.status='In progress';v.checkin=new Date().toISOString();v.tasks=[false,false,false];v.note='';log(`Simulated check-in: ${cn(v.client).name}`);render();toast('Simulated check-in recorded. No location collected.');return {id:v.id,status:v.status};}
function completeVisit(id){const v=visits.find(v=>v.id===id);if(!v||v.status!=='In progress')throw Error('No active visit to complete.');if(!v.tasks.every(Boolean)||!v.note.trim())throw Error('Complete all three tasks and add a visit note before checking out.');v.status='Completed';v.checkout=new Date().toISOString();log(`Completed visit: ${cn(v.client).name}`);render();toast('Visit completed. Overview has been updated.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.tab)go(b.dataset.tab);if(b.dataset.go)go(b.dataset.go);if(b.dataset.action==='add-client')clientModal();if(b.dataset.action==='add-visit')visitModal();if(b.dataset.editClient)clientModal(Number(b.dataset.editClient));if(b.dataset.editVisit)visitModal(Number(b.dataset.editVisit));if(b.dataset.checkin)startVisit(Number(b.dataset.checkin));if(b.dataset.checkout)completeVisit(Number(b.dataset.checkout));}catch(err){toast(err.message)}});
$('.brand').onclick=e=>{e.preventDefault();go('overview')};$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();$('#reset').onclick=()=>showModal('Reset the demonstration?','<p>This clears your changes and restores the original fictional clients and visits.</p>',()=>{seed();toast('Demo restored.');});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.dataset.note){visits.find(v=>v.id===Number(e.target.dataset.note)).note=e.target.value;}});
document.addEventListener('change',e=>{if(e.target.id==='care-select'){selectedCaregiver=Number(e.target.value);render()}if(e.target.dataset.task){const [id,i]=e.target.dataset.task.split(':').map(Number);visits.find(v=>v.id===id).tasks[i]=e.target.checked}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-visit]');if(card)e.dataTransfer.setData('text/plain',card.dataset.visit)});
document.addEventListener('dragover',e=>{const day=e.target.closest('[data-day]');if(day){e.preventDefault();day.classList.add('dragover')}});
document.addEventListener('dragleave',e=>{const day=e.target.closest('[data-day]');if(day&&!day.contains(e.relatedTarget))day.classList.remove('dragover')});
document.addEventListener('drop',e=>{const day=e.target.closest('[data-day]');if(!day)return;e.preventDefault();document.querySelectorAll('.dragover').forEach(x=>x.classList.remove('dragover'));const v=visits.find(v=>v.id===Number(e.dataTransfer.getData('text/plain')));if(!v||v.status!=='Scheduled')return;const updated={...v,date:day.dataset.day};if(conflict(updated,v.id)){toast('Schedule conflict. This client or caregiver already has a visit at that time.');return;}v.date=updated.date;log(`Moved ${cn(v.client).name}'s visit to ${v.date}`);render();toast('Visit moved.');});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_demo_visits',description:'Read fictional home care visits currently shown in this in-memory demonstration.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({visits:visits.map(v=>({id:v.id,client:cn(v.client).name,caregiver:cg(v.caregiver).name,date:v.date,time:v.time,status:v.status}))})})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'start_simulated_visit',description:'Start a scheduled visit on the sample day. Records an in-memory timestamp and updates the interface; does not collect location or send data.',inputSchema:{type:'object',properties:{visitId:{type:'integer'}},required:['visitId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.visitId))throw Error('visitId must be an integer');return startVisit(input.visitId);}})).catch(()=>{});}catch{}}
